<?php

// Read-only local preview of the one synthetic PDF generated by F08ReceiptPdfFixture.
$path = getenv('F08_PREVIEW_PDF');
if ($_SERVER['REQUEST_URI'] !== '/receipt.pdf' || ! $path || ! str_starts_with(realpath($path) ?: '', realpath(__DIR__.'/../../storage/app').DIRECTORY_SEPARATOR)) {
    http_response_code(404);
    exit;
}
header('Content-Type: application/pdf');
header('Cache-Control: no-store');
readfile($path);
